-- Generated by `npm run catalog:import` from PokéAPI's "extended-sinnoh" Pokédex
-- (210 species). Do not edit by hand: rerun the script into a new migration.
on conflict (pokedex_number) do update set
  name = excluded.name,
  types = excluded.types,
  sprite_url = excluded.sprite_url,
  official_artwork_url = excluded.official_artwork_url,
  is_starter = excluded.is_starter,
  is_legendary = excluded.is_legendary,
  evolves_to_pokedex_number = excluded.evolves_to_pokedex_number,
  evolution_min_level = excluded.evolution_min_level,
  catalog_version = 2,
  imported_at = now();
